show_transform(x, 2, 1); show_transform(x, 0.5, -1);

function show_transform(x, a, t0)
    t = linspace(-6, 6, 2001);
    figure; plot(t, x(t), t, x(a*t - t0), '--'); grid on
    legend('x(t)', sprintf('x(%gt %+g)', a, -t0)); xlabel('t'); title('Time scaling and shifting')
end
